"""Check complete economic definitions and source-rule hash before any reserve/evaluation."""
import json,hashlib
from run import ROOT,R,reg,sha,put
plan=json.loads((R/'plan.json').read_text());rows=json.loads((R/'batch.json').read_text());by={x['fingerprint']:x for x in rows};assert len(rows)==8 and sum(x['scope']=='native' for x in rows)==4
rulehash=hashlib.sha256(json.dumps({'rules':plan['rules'],'costs':plan['component_costs']},sort_keys=True,separators=(',',':')).encode()).hexdigest()
for x in rows:
 sp=json.loads((ROOT/x['spec']).read_text());p=sp['parameters'];assert reg.fingerprint(sp)==x['fingerprint'] and sp['validation_plan']==str((R/'plan.json').relative_to(ROOT))
 if x['scope']=='native':assert sp['logic']==plan['native_ETH_logic'] and p['lookback_days']==x['lookback_days'] in [3,4] and p['trend_lookback_days']==x['trend_lookback_days'] in [27,29] and p['return_hurdle']==x['return_hurdle'] in [.025] and p['exit_buffer_fraction']==0 and p['fixed_entry_notional_usdt']==x['fixed_entry_notional_usdt']==3000 and p['initial_capital_usdt']==10000 and p['raw_entry_notional_fraction_of_initial_capital']==.3
 else:
  b,e=x['source_fingerprints'];assert sp['logic']==plan['rules'] and sp['logic']['native_ETH_rule']==plan['native_ETH_logic'] and p['source_rules_and_costs_sha256']==rulehash and b==plan['fixed_BTC']['fingerprint'] and by[e]['scope']=='native' and [z['fingerprint'] for z in sp['components']]==[b,e] and [z['weight'] for z in sp['components']]==p['raw_component_multipliers']==[1,1] and p['initial_capital_usdt']==20000 and p['component_capitals_usdt']==[10000,10000] and p['component_initial_entry_notionals_usdt']==[1000,3000]
  assert p['BTC_lookback_days']==31 and p['BTC_return_hurdle']==.04 and p['BTC_exit_buffer_fraction']==p['trend_exit_buffer_fraction']==.01 and p['BTC_fixed_entry_notional_usdt']==1000 and p['ETH_fixed_entry_notional_usdt']==3000 and p['ETH_trend_lookback_days']==p['trend_filter_lookback_days']==x['trend_filter_lookback_days']==by[e]['trend_lookback_days'] and p['ETH_lookback_days']==p['reversal_lookback_days']==x['reversal_lookback_days']==by[e]['lookback_days'] and p['ETH_return_hurdle']==p['reversal_return_hurdle']==x['reversal_return_hurdle']==by[e]['return_hurdle'] in [.025] and p['ETH_exit_buffer_fraction']==0
put(R/'definition_check.json',{'passed':True,'checked_configs':8,'new_native':4,'new_parents':4,'plan_sha256':sha(R/'plan.json'),'all_signal_budget_source_aliases_match':True,'no_financial_evaluation':True});print('PASS:8 exact native/parent definitions,full logic/hash/capital/source aliases;no financial evaluation.')
